const items = $input.all();

if (items.length === 0) {
  return [];
}

const ideaId = items[0].json.idea_id;

return [
  {
    json: {
      idea_id: ideaId
    }
  }
];

const idea = $('Get Idea').first().json;

const accounts = $('Get Social Accounts').all();

return [
  {
    json: {
      idea_id: idea.id,
      brand_id: idea.brand_id,
      workspace_id: idea.workspace_id,

      idea: {
        title: idea.title,
        concept: idea.concept,
        objective: idea.objective,
        pillar: idea.pillar,
        format: idea.format,
        hook: idea.hook,
        cta: idea.cta
      },

      available_social_accounts: accounts.map(item => ({
